import { describe, expect, it } from "vitest";
import { roundCents } from "../src/billing/round";

describe("roundCents", () => {
  it("rounds exact half cents to the even cent so invoices don't drift upward", () => {
    expect(roundCents(0.5)).toBe(0);
    expect(roundCents(1.5)).toBe(2);
    expect(roundCents(2.5)).toBe(2);
    expect(roundCents(-2.5)).toBe(-2);
    expect(roundCents(-3.5)).toBe(-4);
  });

  it("rounds non-half fractions to the nearest cent", () => {
    expect(roundCents(1234.49)).toBe(1234);
    expect(roundCents(1234.51)).toBe(1235);
    expect(roundCents(-1.4)).toBe(-1);
    expect(roundCents(-1.6)).toBe(-2);
  });

  it("leaves whole cents unchanged", () => {
    expect(roundCents(100)).toBe(100);
  });
});

